WITH src AS (SELECT * FROM order_items WHERE order_id = 5), agg AS (SELECT CASE WHEN unit_price >= 420 THEN 'high' WHEN unit_price >= 150 THEN 'mid' ELSE 'low' END AS unit_price_bucket, order_id, MAX(quantity) AS max_quantity, MIN(quantity) AS min_quantity FROM src GROUP BY CASE WHEN unit_price >= 420 THEN 'high' WHEN unit_price >= 150 THEN 'mid' ELSE 'low' END, order_id) SELECT unit_price_bucket, order_id, max_quantity, min_quantity FROM agg ORDER BY unit_price_bucket, order_id DESC
